# ---------- parse: basics ----------

def test_parse_readme_example():
    xml = """
    <mydocument has="an attribute">
      <and>
        <many>elements</many>
        <many>more elements</many>
      </and>
      <plus a="complex">
        element as well
      </plus>
    </mydocument>
    """
    assert parse(xml) == {
        "mydocument": {
            "@has": "an attribute",
            "and": {"many": ["elements", "more elements"]},
            "plus": {"@a": "complex", "#text": "element as well"},
        }
    }


def test_parse_simple_text():
    assert parse("<a>hello</a>") == {"a": "hello"}


def test_parse_empty_element_is_none():
    assert parse("<a><b/></a>") == {"a": {"b": None}}


