    assert isinstance(result, OrderedDict)
    assert isinstance(result["a"], OrderedDict)
    assert result == {"a": {"@x": "1", "b": "2"}}


def test_postprocessor():
    def pp(path, key, value):
        try:
            return key + ":int", int(value)
        except (ValueError, TypeError):
            return key, value
    result = parse("<a><b>1</b><b>2</b><b>x</b></a>", postprocessor=pp)
    assert result == {"a": {"b:int": [1, 2], "b": "x"}}


def test_postprocessor_returning_none_drops_item():
    def pp(path, key, value):
        if key == "b":
            return None
        return key, value
    assert parse("<a><b>1</b><c>2</c></a>", postprocessor=pp) == {"a": {"c": "2"}}


# ---------- namespaces ----------

NS_XML = """
<root xmlns="http://defaultns.com/"
      xmlns:a="http://a.com/"
      xmlns:b="http://b.com/">
  <x>1</x>
  <a:y>2</a:y>
  <b:z>3</b:z>
</root>
"""


def _without_xmlns(d):
    # Newer versions may report namespace declarations under "@xmlns".
    d = dict(d)
    d.pop("@xmlns", None)
    return d


def test_namespaces_expanded():
    result = parse(NS_XML, process_namespaces=True)
    assert list(result.keys()) == ["http://defaultns.com/:root"]
    assert _without_xmlns(result["http://defaultns.com/:root"]) == {
        "http://defaultns.com/:x": "1",
        "http://a.com/:y": "2",
        "http://b.com/:z": "3",
    }


def test_namespaces_collapsed_and_skipped():
    namespaces = {"http://defaultns.com/": None, "http://a.com/": "ns_a"}
    result = parse(NS_XML, process_namespaces=True, namespaces=namespaces)
    assert list(result.keys()) == ["root"]
    assert _without_xmlns(result["root"]) == {
        "x": "1", "ns_a:y": "2", "http://b.com/:z": "3"
    }


def test_no_namespace_processing_by_default():
    result = parse('<a xmlns:n="http://n/"><n:b>1</n:b></a>')
    assert result["a"]["n:b"] == "1"
    assert result["a"]["@xmlns:n"] == "http://n/"


