def test_streaming_item_depth():
    items = []

    def cb(path, item):
        # copy the path: the parser keeps mutating the same list
        items.append((list(path), item))
        return True

    result = parse('<a prop="x"><b>1</b><b>2</b></a>', item_depth=2, item_callback=cb)
    assert result is None
    assert items == [
        ([("a", {"prop": "x"}), ("b", None)], "1"),
        ([("a", {"prop": "x"}), ("b", None)], "2"),
    ]


def test_streaming_dict_items():
    items = []
    parse("<a><b><n>1</n></b><b><n>2</n></b></a>", item_depth=2,
          item_callback=lambda p, i: items.append(i) or True)
    assert items == [{"n": "1"}, {"n": "2"}]


def test_streaming_callback_false_interrupts():
    calls = []

    def cb(path, item):
        calls.append(item)
        return False

    with pytest.raises(ParsingInterrupted):
        parse("<a><b>1</b><b>2</b></a>", item_depth=2, item_callback=cb)
    assert calls == ["1"]


